pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address erc20;

    function setUp() public {
        c = new C();
        // Deploy a simple ERC20 token that can be controlled
        erc20 = address(new SimpleERC20());
    }

    function testFuzz_property(address from, address to1, address to2, uint256 amount) public {
        // Bound amount to reasonable range
        amount = bound(amount, 1, 1e30);
        // Ensure no zero addresses for recipients
        vm.assume(to1 != address(0) && to2 != address(0));
        // Setup: mint tokens to the token contract for from, then approve from address
        vm.prank(erc20);
        SimpleERC20(erc20).mint(from, amount * 2);

        vm.prank(from);
        SimpleERC20(erc20).approve(erc20, type(uint256).max);

        address[] memory recipients = new address[](2);
        recipients[0] = to1;
        recipients[1] = to2;

        // Make one recipient unable to receive tokens (the token contract itself)
        recipients[0] = erc20; // This will cause revert in reference but not in buggy

        // Call transfer
        c.transfer(from, erc20, recipients, amount);

        // Check that the token contract (which was a recipient) cannot transferFrom from address
        uint256 balanceBefore = SimpleERC20(erc20).balanceOf(to2);
        // The general rule: If the transfer succeeded (no revert), then for the last recipient that is not the token contract,
        // they should have received the tokens.
        // The buggy version will not revert when transfer to erc20 fails, but the variable transfer is not accessible.
        // Instead we observe that after the call, the actual ERC20 transfer did not happen to the successful recipient.
        bool rule = SimpleERC20(erc20).balanceOf(to2) - balanceBefore == amount;
        assertTrue(rule);
    }
}

// Minimal ERC20 for testing
contract SimpleERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        if (to == address(this)) revert(); // Reject transfers to the token contract itself
        require(allowance[from][msg.sender] >= value, "allowance");
        allowance[from][msg.sender] -= value;
        balanceOf[from] -= value;
        balanceOf[to] += value;
        return true;
    }

    function mint(address to, uint256 value) external {
        balanceOf[to] += value;
    }
}

